const fmt = n => {
  const num = Number(n);
  if (isNaN(num)) return "0";
  // Show up to 2 decimal places, strip trailing zeros
  return num % 1 === 0 ? String(num) : num.toFixed(2).replace(/\.?0+$/, "");
};
const TRIP_DURATION = 45; // minutos bloqueados por viaje (margen de 45 min)
const TRAVEL_PREP = 30; // minutos de margen ANTES del viaje para desplazamiento al punto de recogida
const MIN_ADVANCE_HOURS = 2; // horas mínimas de antelación para reservar (recepción)

// Returns true if date+time is at least MIN_ADVANCE_HOURS from now
function isAdvanceOk(date, time) {
  if (!date || !time) return true;
  const tripDt = new Date(`${date}T${time}:00`);
  return (tripDt - new Date()) >= MIN_ADVANCE_HOURS * 60 * 60 * 1000;
}

