function ChatNotifBanner({ notif, bookings, onOpen, onDismiss }) {
  if (!notif) return null;
  const booking = bookings.find(b => b.id === notif.bookingId);
  if (!booking) return null;
  const msg = notif.msg;
  return (
    <div onClick={()=>{ onOpen(booking); onDismiss(); }} style={{
      position:"fixed", top:0, left:"50%", transform:"translateX(-50%)",
      width:"100%", maxWidth:420, zIndex:500,
      background:"linear-gradient(135deg,#1e293b,#0f172a)",
      borderBottom:"2px solid #2563eb",
      padding:"10px 16px",
      display:"flex", alignItems:"center", gap:12,
      cursor:"pointer", animation:"slideDown 0.3s ease",
      boxShadow:"0 4px 20px rgba(0,0,0,0.6)",
    }}>
      
      {/* Avatar */}
      <div style={{
        width:36, height:36, borderRadius:"50%", flexShrink:0,
        background:"#2563eb20", border:"1.5px solid #2563eb44",
        display:"flex", alignItems:"center", justifyContent:"center",
        fontSize:16,
      }}>💬</div>
      {/* Content */}
      <div style={{flex:1, minWidth:0}}>
        <div style={{display:"flex", justifyContent:"space-between", marginBottom:2}}>
          <span style={{color:"#2563eb", fontSize:11, fontWeight:700}}>{msg.fromName}</span>
          <span style={{color:"#475569",fontSize:10}}>{typeof msg.ts==="number"?new Date(msg.ts).toLocaleTimeString("es-ES",{hour:"2-digit",minute:"2-digit"}):msg.ts}</span>
        </div>
        <div style={{color:"#64748b", fontSize:11, marginBottom:1}}>{booking.guest} · {booking.time}</div>
        <div style={{color:"#0f172a", fontSize:12, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap"}}>{msg.text}</div>
      </div>
      {/* Dismiss */}
      <button onClick={e=>{e.stopPropagation();onDismiss();}} style={{
        background:"none", border:"none", color:"#475569", fontSize:18,
        cursor:"pointer", padding:"0 4px", flexShrink:0,
      }}>×</button>
    </div>
  );
}

