// ─── HELPERS ─────────────────────────────────────────────────────────────────
const t2m = t => { const [h,m]=t.split(":").map(Number); return h*60+m; };
const m2t = m => `${String(Math.floor(m/60)%24).padStart(2,"0")}:${String(m%60).padStart(2,"0")}`;


// Devuelve true si la hora está libre (sin viaje en ±30 min)
function isSlotFree(bookings, date, time, blockedSlots) {
  // Check driver blocks first
  if (blockedSlots && (blockedSlots[date]||[]).includes(time)) return false;
  const req = t2m(time);
  // Also block if within TRIP_DURATION of any blocked slot
  if (blockedSlots && (blockedSlots[date]||[]).some(bt=>{
    const bm = t2m(bt);
    return req >= bm && req < bm + TRIP_DURATION;
  })) return false;
  return !bookings.some(b => {
    if (b.date !== date) return false;
    if (["rejected","cancelled","completed"].includes(b.status)) return false;
    const s = t2m(b.time);
    // Block TRAVEL_PREP (30 min) before trip start to allow travel to pickup point
    // and TRIP_DURATION (45 min) after trip start for the trip itself
    return req >= s - TRAVEL_PREP && req < s + TRIP_DURATION;
  });
}

// Genera lista de slots libres para una fecha dada (cada 30 min, 06:00–22:00)
function getFreeSlots(bookings, date) {
  const slots = [];
  for (let m = 360; m <= 1320; m += 30) {
    const time = m2t(m);
    if (isSlotFree(bookings, date, time)) slots.push(time);
  }
  return slots;
}

function statusLabel(s) { return {confirmed:"Confirmado",pending:"Pendiente",rejected:"Rechazado",inprogress:"En Curso",completed:"Completado",cancelled:"Cancelado",price_proposed:"Precio Propuesto",client_rejected:"Rechazado por Cliente"}[s]||s; }
function statusColor(s) { return {confirmed:"#2563eb",pending:"#f59e0b",rejected:"#ef4444",inprogress:"#3b82f6",completed:"#22c55e",cancelled:"#f97316",price_proposed:"#a78bfa",client_rejected:"#f97316"}[s]||"#64748b"; }
function mapsUrl(a) { return `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(a)}`; }
function mapsRouteUrl(o, d) { return `https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(o)}&destination=${encodeURIComponent(d)}&travelmode=driving`; }
function initials(n) { return n.split(" ").map(w=>w[0]).join("").slice(0,2).toUpperCase(); }

