// ─── REMINDER SYSTEM ─────────────────────────────────────────────────────────
// Comprueba cada 30 s si hay viajes confirmados a ≤30 min y aún no notificados.
// Lanza notificación nativa del navegador + alerta en-app.
// ─── SERVICE WORKER + NOTIFICATION SYSTEM ────────────────────────────────────
const _swReg = { current: null };

async function _registerSW() {
  if (!("serviceWorker" in navigator)) return;
  try {
    const reg = await navigator.serviceWorker.register("./sw.js", { scope: "./" });
    _swReg.current = reg;
  } catch(e) { /* SW not available in this context */ }
}

async function _requestPermission() {
  if (!("Notification" in window)) return false;
  if (Notification.permission === "granted") return true;
  const r = await Notification.requestPermission();
  return r === "granted";
}

function sendNotification(title, body, tag) {
  if (navigator.vibrate) navigator.vibrate([200,100,200,100,200]);
  if (!("Notification" in window) || Notification.permission !== "granted") return;
  // Via SW (works in background tab)
  if (_swReg.current) {
    if (navigator.serviceWorker.controller) {
      navigator.serviceWorker.controller.postMessage({ type:"SHOW_NOTIFICATION", title, body, tag: tag||"nexttrip-"+Date.now() });
      return;
    }
    _swReg.current.showNotification(title, { body, tag: tag||"nexttrip", icon:"/icon.png", vibrate:[150,80,150], renotify:true }).catch(()=>{});
    return;
  }
  // Fallback
  try { new Notification(title, { body, tag: tag||"nexttrip" }); } catch {}
}

// Register SW immediately
if (typeof window !== "undefined") {
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", _registerSW);
  } else {
    _registerSW();
  }
}

function useReminderNotifications(bookings, isDriverActive) {
  const notifiedRef = useRef(new Set());
  const [inAppAlert, setInAppAlert] = useState(null);

  useEffect(() => {
    if (!isDriverActive) return;
    _requestPermission();
  }, [isDriverActive]);

  useEffect(() => {
    if (!isDriverActive) return;

    const check = () => {
      const now = new Date();
      const todayStr = now.toISOString().slice(0, 10);
      const nowMins = now.getHours() * 60 + now.getMinutes();

      bookings
        .filter(b => b.status === "confirmed" && b.date === todayStr)
        .forEach(b => {
          if (notifiedRef.current.has(b.id)) return;
          const tripMins = t2m(b.time);
          const diff = tripMins - nowMins;
          if (diff > 0 && diff <= 30) {
            notifiedRef.current.add(b.id);
            const minsLeft = Math.round(diff);
            const mapsLink = mapsUrl(b.origin);
            // Push via SW for background
            sendNotification(
              `🚗 NextTrip — Viaje en ${minsLeft} min`,
              `${b.guest} · ${b.origin}`,
              `trip-${b.id}`
            );
            setInAppAlert({ booking: b, minsLeft, mapsLink });
          }
        });
    };

    check();
    const interval = setInterval(check, 30_000);
    return () => clearInterval(interval);
  }, [bookings, isDriverActive]);

  return { inAppAlert, dismissAlert: () => setInAppAlert(null) };
}

