const MIN_FARE = 30;


// ─── CLIENT VIEW ──────────────────────────────────────────────────────────────


// --- CHAT TEMPLATES ---
const DRIVER_TEMPLATES = [
  {es:"Estoy en camino",       en:"I am on my way"},
  {es:"Llegando en 5 minutos", en:"Arriving in 5 minutes"},
  {es:"Esperando en la direccion acordada", en:"Waiting at the agreed address"},
  {es:"He llegado",            en:"I have arrived"},
];

function ChatModal({ booking, messages, onSend, currentUser, isDriver, onClose, onMarkRead, accentColor, clientLang }) {
  const [text, setText] = useState("");
  const [showTemplates,setShowTemplates]=useState(false);
  const bottomRef = useRef(null);
  const b = booking;
  const bookingKey = String(b.id);
  const allUsers = [...EMPLOYEES, ...loadUsers()];
  const emp = allUsers.find(e => e.id === b.employeeId);
  const thread = messages[bookingKey] || [];
  // Color scheme: purple for VIP client chats, gold for reception
  const isVip = b.isClientBooking || accentColor === "#a78bfa";
  const COLOR = isVip ? "#a78bfa" : "#2563eb";
  const COLOR_DARK = isVip ? "#7c3aed" : "#a07840";
  const COLOR_BG   = isVip ? "#eff6ff" : "#1a130a";
  const BADGE_LABEL = isVip ? "💜 VIP CLIENT" : "🏨 RECEPCIÓN";

  // Mark as read immediately when chat opens
  useEffect(() => {
    const relevant = thread.filter(m => isDriver ? m.from !== "driver" : m.from === "driver");
    if (onMarkRead) onMarkRead(bookingKey, relevant.length);
  }, []); // eslint-disable-line

  // Scroll to bottom on new messages
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [thread.length]);

  const handleClose = () => {
    // Mark as read on close too (in case new messages arrived while open)
    const relevant = thread.filter(m => isDriver ? m.from !== "driver" : m.from === "driver");
    if (onMarkRead) onMarkRead(bookingKey, relevant.length);
    onClose();
  };

  const send = () => {
    if (!text.trim()) return;
    onSend(bookingKey, {
      id: Date.now(),
      from: isDriver ? "driver" : currentUser.id,
      fromName: isDriver ? "DRIVER 🚗" : currentUser.name,
      fromAvatar: isDriver ? "#2563eb" : currentUser.avatar,
      text: text.trim(),
      ts: new Date().toLocaleTimeString("es-ES", { hour:"2-digit", minute:"2-digit" }),
    });
    setText("");
  };

  return (
    <div onClick={handleClose} style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.85)",zIndex:300,display:"flex",alignItems:"flex-end"}}>
      <div onClick={e=>e.stopPropagation()} style={{
        background:"#ffffff", borderRadius:"22px 22px 0 0", width:"100%",
        border:`1px solid ${COLOR}33`, borderBottom:"none",
        display:"flex", flexDirection:"column", maxHeight:"85vh",
      }}>
        {/* Header */}
        <div style={{padding:"16px 18px 12px",borderBottom:`1px solid ${COLOR}22`,flexShrink:0}}>
          <div style={{width:36,height:4,background:"#e2e8f0",borderRadius:2,margin:"0 auto 10px"}}/>
          {/* Back + close row */}
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
            <button onClick={handleClose} style={{
              display:"flex",alignItems:"center",gap:6,background:"none",border:"none",
              color:"#64748b",fontSize:13,cursor:"pointer",padding:0,fontFamily:"inherit",
            }}>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#64748b" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <path d="M19 12H5M12 19l-7-7 7-7"/>
              </svg>
              Volver
            </button>
            {/* Source badge */}
            {isDriver&&<div style={{background:COLOR+"22",border:`1px solid ${COLOR}44`,borderRadius:20,padding:"3px 10px"}}>
              <span style={{color:COLOR,fontSize:9,fontWeight:700,letterSpacing:1}}>{BADGE_LABEL}</span>
            </div>}
            <button onClick={handleClose} style={{
              background:"#f1f5f9",border:"1px solid #2a3a4a",borderRadius:"50%",
              width:30,height:30,cursor:"pointer",color:"#64748b",fontSize:16,
              display:"flex",alignItems:"center",justifyContent:"center",
            }}>×</button>
          </div>
          <div style={{display:"flex",alignItems:"center",gap:10}}>
            <div style={{flex:1}}>
              <div style={{color:"#64748b",fontSize:9,letterSpacing:2,marginBottom:3}}>CHAT DE RESERVA</div>
              <div style={{color:"#0f172a",fontSize:15,fontFamily:"'Inter',sans-serif",fontWeight:700}}>{b.guest}</div>
              <div style={{color:COLOR,fontSize:10,marginTop:1}}>{b.hotel} · {b.date} {b.time}</div>
            </div>
            {/* Show who's on the other side */}
            {isDriver && emp ? (
              <div style={{display:"flex",alignItems:"center",gap:6,background:emp.avatar+"15",border:`1px solid ${emp.avatar}33`,borderRadius:8,padding:"5px 10px"}}>
                <div style={{width:22,height:22,borderRadius:"50%",background:emp.avatar+"30",border:`1.5px solid ${emp.avatar}66`,display:"flex",alignItems:"center",justifyContent:"center",color:emp.avatar,fontSize:9,fontWeight:700}}>{initials(emp.name)}</div>
                <div>
                  <div style={{color:emp.avatar,fontSize:11,fontWeight:600}}>{emp.name}</div>
                  <div style={{color:"#64748b",fontSize:9}}>{emp.hotel.split(" ").slice(-1)[0]}</div>
                </div>
              </div>
            ) : isDriver && isVip ? (
              <div style={{display:"flex",alignItems:"center",gap:6,background:"#a78bfa15",border:"1px solid #a78bfa33",borderRadius:8,padding:"5px 10px"}}>
                <div style={{width:22,height:22,borderRadius:"50%",background:"#a78bfa25",border:"1.5px solid #a78bfa55",display:"flex",alignItems:"center",justifyContent:"center",color:"#a78bfa",fontSize:9,fontWeight:700}}>VIP</div>
                <span style={{color:"#a78bfa",fontSize:11,fontWeight:600}}>{b.guest.split(" ")[0]}</span>
              </div>
            ) : !isDriver ? (
              <div style={{display:"flex",alignItems:"center",gap:6,background:`${COLOR}15`,border:`1px solid ${COLOR}33`,borderRadius:8,padding:"5px 10px"}}>
                <LuxuryCarIcon size={28} color={COLOR}/>
                <span style={{color:COLOR,fontSize:11,fontWeight:700}}>DRIVER</span>
              </div>
            ) : null}
          </div>
        </div>

        {/* Messages */}
        <div style={{flex:1,overflowY:"auto",padding:"14px 16px",display:"flex",flexDirection:"column",gap:10}}>
          {thread.length === 0 && (
            <div style={{textAlign:"center",color:"#94a3b8",fontSize:12,marginTop:20}}>
              No hay mensajes aún. ¡Empieza la conversación!
            </div>
          )}
          {thread.map(msg => {
            const mine = isDriver ? msg.from === "driver" : msg.from === currentUser?.id;
            return (
              <div key={msg.id} style={{display:"flex",flexDirection:"column",alignItems:mine?"flex-end":"flex-start"}}>
                {!mine && (
                  <div style={{display:"flex",alignItems:"center",gap:5,marginBottom:3}}>
                    <div style={{width:16,height:16,borderRadius:"50%",background:msg.fromAvatar+"30",border:`1px solid ${msg.fromAvatar}55`,display:"flex",alignItems:"center",justifyContent:"center",color:msg.fromAvatar,fontSize:8,fontWeight:700}}>{msg.fromName[0]}</div>
                    <span style={{color:"#64748b",fontSize:10}}>{msg.fromName}</span>
                  </div>
                )}
                <div style={{
                  maxWidth:"80%",
                  background:mine
                    ?`linear-gradient(135deg,${COLOR},${COLOR_DARK})`
                    :"#f1f5f9",
                  border:mine?"none":"1px solid #e2e8f0",
                  borderRadius:mine?"14px 14px 4px 14px":"14px 14px 14px 4px",
                  padding:"9px 13px",
                }}>
                  <div style={{color:mine?"#ffffff":"#0f172a",fontSize:13,lineHeight:1.4,fontWeight:600}}>{msg.text}</div>
                  <div style={{color:mine?"rgba(255,255,255,0.65)":"#94a3b8",fontSize:10,marginTop:3,textAlign:"right"}}>{typeof msg.ts==="number"?new Date(msg.ts).toLocaleTimeString("es-ES",{hour:"2-digit",minute:"2-digit"}):msg.ts}</div>
                </div>
              </div>
            );
          })}
          <div ref={bottomRef}/>
        </div>

        {/* Input */}
        <div style={{padding:"10px 14px 24px",borderTop:`1px solid ${COLOR}22`,display:"flex",gap:8,flexShrink:0,background:"#f8fafc",flexWrap:"wrap"}}>
          {isDriver&&<button onClick={()=>setShowTemplates(s=>!s)} style={{background:"none",border:"1px solid #2563eb33",borderRadius:20,color:"#64748b",fontSize:11,padding:"4px 12px",cursor:"pointer",marginBottom:8}}>Respuestas rapidas</button>}
          {isDriver&&showTemplates&&(
            <div style={{marginBottom:8}}>
              {DRIVER_TEMPLATES.map((tpl,i)=>(
                <button key={i} onClick={()=>{onSend(String(b.id),{id:Date.now(),from:"driver",fromName:"DRIVER",fromAvatar:"#2563eb",text:clientLang==="en"?tpl.en:tpl.es,ts:new Date().toLocaleTimeString("es-ES",{hour:"2-digit",minute:"2-digit"})});setShowTemplates(false);}} style={{display:"block",width:"100%",background:"#f1f5f9",border:"1px solid #2563eb33",borderRadius:8,color:"#0f172a",fontSize:12,padding:"8px 12px",cursor:"pointer",textAlign:"left",marginBottom:4}}>
                  {tpl.es}{clientLang==="en"&&<span style={{color:"#2563eb",fontSize:10,marginLeft:8}}>{tpl.en}</span>}
                </button>
              ))}
            </div>
          )}
          <input
            value={text}
            onChange={e=>setText(e.target.value)}
            onKeyDown={e=>{ if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();send();}}}
            placeholder="Escribe un mensaje..."
            style={{flex:1,background:"#f1f5f9",border:`1px solid ${COLOR}33`,borderRadius:24,
              padding:"10px 16px",color:"#0f172a",fontSize:13,outline:"none"}}
          />
          <button onClick={send} disabled={!text.trim()} style={{
            width:42,height:42,borderRadius:"50%",border:"none",cursor:"pointer",flexShrink:0,
            background:text.trim()?`linear-gradient(135deg,${COLOR},${COLOR_DARK})`:"#f1f5f9",
            color:text.trim()?"#f8fafc":"#334155",
            fontSize:18,display:"flex",alignItems:"center",justifyContent:"center",
            transition:"all 0.15s",
          }}>➤</button>
        </div>
      </div>
    </div>
  );
}

