// ─── ERROR BOUNDARY ──────────────────────────────────────────────────────────
class ErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { error: null }; }
  static getDerivedStateFromError(e) { return { error: e }; }
  componentDidCatch(e, info) { console.error("CRASH:", e, info); }
  render() {
    if (this.state.error) {
      return (
        <div style={{
          minHeight:"100vh", background:"#f8fafc", display:"flex", flexDirection:"column",
          alignItems:"center", justifyContent:"center", padding:24, fontFamily:"sans-serif",
        }}>
          <div style={{
            background:"#f1f5f9", border:"1.5px solid #ef4444", borderRadius:16,
            padding:24, maxWidth:400, width:"100%",
          }}>
            <div style={{color:"#ef4444", fontSize:16, fontWeight:700, marginBottom:12}}>⚠️ Error en la app</div>
            <div style={{color:"#0f172a", fontSize:12, fontFamily:"monospace", wordBreak:"break-all",
              background:"#ffffff", borderRadius:8, padding:12, marginBottom:16}}>
              {this.state.error.toString()}
            </div>
            <button onClick={()=>window.location.reload()} style={{
              width:"100%", background:"linear-gradient(135deg,#2563eb,#a07840)",
              border:"none", borderRadius:10, padding:"12px 0",
              color:"#0f172a", fontWeight:700, fontSize:14, cursor:"pointer",
            }}>Recargar app</button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

export default function RivieraApp({ initialRole=null }) {
  const [screen,setScreen]=useState(initialRole==="driver"?"driver-login":initialRole==="reception"?"reception-auth":"roles");
  const [isOnline,setIsOnline]=useState(navigator.onLine);

  useEffect(()=>{
    const on=()=>setIsOnline(true);
    const off=()=>setIsOnline(false);
    window.addEventListener('online',on);
    window.addEventListener('offline',off);
    return()=>{ window.removeEventListener('online',on); window.removeEventListener('offline',off); };
  },[]);
  const [installPrompt,setInstallPrompt]=useState(null);
  const [showInstall,setShowInstall]=useState(false);
  const [showDriverMenu,setShowDriverMenu]=useState(false);
  const [showEmpProfile,setShowEmpProfile]=useState(false);
  const [empOriginDraft,setEmpOriginDraft]=useState({name:"",address:""});
  const [empPinView,setEmpPinView]=useState(false);
  const [empPinCurrent,setEmpPinCurrent]=useState("");
  const [empPinNew,setEmpPinNew]=useState("");
  const [empPinConfirm,setEmpPinConfirm]=useState("");
  const [empPinError,setEmpPinError]=useState("");
  const [empPinSuccess,setEmpPinSuccess]=useState(false);
  useEffect(()=>{
    const handler=e=>{e.preventDefault();setInstallPrompt(e);setShowInstall(true);};
    window.addEventListener('beforeinstallprompt',handler);
    return()=>window.removeEventListener('beforeinstallprompt',handler);
  },[]);
  const handleInstall=async()=>{
    if(!installPrompt)return;
    installPrompt.prompt();
    const{outcome}=await installPrompt.userChoice;
    if(outcome==="accepted"){setShowInstall(false);setInstallPrompt(null);}
  };
  const [currentEmployee,setCurrentEmployee]=useState(null);
  const [bookings,setBookings]=useState(() => {
    const saved = loadBookings();
    return saved || [];
  });
  // Sync users from Firebase on mount
  useEffect(()=>{
    fbGet("nexttrip/users").then(d=>{
      if(d?.data?.length) { try{localStorage.setItem(USERS_KEY,JSON.stringify(d.data));}catch{} }
    });
  },[]);

  // ── FIREBASE SYNC ──────────────────────────────────────────────────────────
  // Rule: Firebase is the only source of truth.
  // We NEVER auto-push local state to Firebase. Each action handler calls
  // fbSave() explicitly after mutating state.
  // The listener only reads from Firebase → updates local state.
  useEffect(() => {
    const unsub = fbListen("nexttrip/bookings", (data) => {
      if (!data || !data.data) return;
      const remote = sanitizeBookings(data.data);
      if (!remote) return;
      // Auto-cancel expired price_proposed bookings
      const now = new Date();
      const cleaned = remote.map(b => {
        if (b.status === "price_proposed" && new Date(`${b.date}T${b.time}:00`) < now) {
          return {...b, status: "cancelled", cancelReason: "Expirado — sin confirmación del cliente"};
        }
        return b;
      });
      const hasChanges = cleaned.some((b,i) => b.status !== remote[i].status);
      if (hasChanges) {
        fbSet("nexttrip/bookings", { data: cleaned, updatedAt: Date.now() });
      }
      const final = hasChanges ? cleaned : remote;
      setBookings(prev => {
        if (JSON.stringify(prev) === JSON.stringify(final)) return prev;
        try { localStorage.setItem(BOOKINGS_KEY, JSON.stringify(final)); } catch {}
        return final;
      });
    });
    return () => unsub();
  }, []);
  const [toast,setToast]=useState(null);
  const [driverAlert,setDriverAlert]=useState(null);
  const [driverPriceConfig,setDriverPriceConfig]=useState(false);
  const [driverPriceClient,setDriverPriceClient]=useState(()=>{try{return Number(localStorage.getItem("ntprice_client")||3.15);}catch{return 3.15;}});
  const [driverPriceRecep,setDriverPriceRecep]=useState(()=>{try{return Number(localStorage.getItem("ntprice_recep")||3.15);}catch{return 3.15;}});
  const [draftPriceClient,setDraftPriceClient]=useState("3.15");
  const [draftPriceRecep,setDraftPriceRecep]=useState("3.15");
  const [notifDismissed,setNotifDismissed]=useState(false);
  const [driverStatus,setDriverStatus]=useState("free");
  useEffect(()=>{
    try{localStorage.setItem("nexttrip_driver_status",driverStatus);}catch{}
    // Use merge-style write so serviceStatus is preserved
    fbGet("nexttrip/status").then(current=>{
      const existing = current || {};
      fbSet("nexttrip/status", { ...existing, driverStatus, updatedAt: Date.now() });
    });
  },[driverStatus]);
  // Sync driverStatus from Firebase on mount
  useEffect(()=>{
    fbGet("nexttrip/status").then(d=>{ if(d?.driverStatus) setDriverStatus(d.driverStatus); });
  },[]);
  // serviceStatus: "online" | "offline"
  const [serviceStatus,setServiceStatus]=useState({status:"online",returnDate:""});
  useEffect(()=>{
    fbGet("nexttrip/status").then(d=>{ if(d?.serviceStatus) setServiceStatus(d.serviceStatus); });
    const unsub = fbListen("nexttrip/status", d=>{
      if(d?.serviceStatus) setServiceStatus(d.serviceStatus);
      if(d?.driverStatus) setDriverStatus(d.driverStatus);
    });
    return ()=>unsub();
  },[]);
  const handleSetService=(s)=>{
    setServiceStatus(s);
    try { localStorage.setItem("nexttrip_service", JSON.stringify(s)); } catch {}
    fbGet("nexttrip/status").then(current=>{
      const existing = current || {};
      fbSet("nexttrip/status", { ...existing, serviceStatus: s, updatedAt: Date.now() });
    });
  };
  // blockedSlots: { "2026-05-23": ["09:00","10:30",...], ... }
  const [blockedSlots,setBlockedSlots]=useState(()=>loadBlocks());

  // Persist blocked slots to Firebase
  useEffect(()=>{ saveBlocks(blockedSlots); },[blockedSlots]);
  // Sync blocks from Firebase
  useEffect(()=>{
    const unsub = fbListen("nexttrip/blocks", d=>{
      if(d?.data) { setBlockedSlots(d.data); try{localStorage.setItem(BLOCKS_KEY,JSON.stringify(d.data));}catch{} }
    });
    return ()=>unsub();
  },[]);

  const handleToggleBlock=(date,time)=>{
    setBlockedSlots(prev=>{
      const daySlots = prev[date]||[];
      const isBlocked = daySlots.includes(time);
      const updated = isBlocked
        ? daySlots.filter(t=>t!==time)
        : [...daySlots, time];
      return {...prev, [date]: updated};
    });
  };
  const [messages,setMessages]=useState({});
  // Real-time Firebase sync for messages
  useEffect(()=>{
    const unsub = fbListen("nexttrip/messages", (data) => {
      if (!data || !data.data) return;
      setMessages(prev => {
        const remote = data.data;
        let changed = false;
        const merged = {...prev};
        Object.entries(remote).forEach(([bid,msgs]) => {
          if (!prev[bid] || msgs.length > prev[bid].length) { merged[bid]=msgs; changed=true; }
        });
        return changed ? merged : prev;
      });
    });
    return () => unsub();
  },[]);

  // prevBookingsRef kept for compatibility
  const prevBookingsRef = useRef([]);
  // Track read state: { [bookingId]: lastReadCount }
  const [readCounts,setReadCounts]=useState(()=>{
    try{return JSON.parse(localStorage.getItem("nexttrip_read_counts")||"{}");}catch{return {};}
  });
  useEffect(()=>{
    try{localStorage.setItem("nexttrip_read_counts",JSON.stringify(readCounts));}catch{}
  },[readCounts]);
  const [chatNotifOpen,setChatNotifOpen]=useState(null);
  const prevPendingRef=useRef(bookings.filter(b=>b.status==="pending").length);

  const isDriver = screen === "driver";
  const { inAppAlert, dismissAlert } = useReminderNotifications(bookings, isDriver);

  const pendingCount=bookings.filter(b=>b.status==="pending").length;
  useEffect(()=>{
    if(pendingCount>prevPendingRef.current)setToast("🔔 Nueva solicitud de viaje recibida");
    prevPendingRef.current=pendingCount;
  },[pendingCount]);

  const handleAccept = id => {
    const booking = bookings.find(b=>b.id===id);
    fbMutateBookings(p=>p.map(b=>b.id===id?{...b,status:"confirmed"}:b), setBookings, (err)=>setToast(err));
    // Send auto-message notifying client/reception
    if(booking) {
      const isEN = booking.clientLang==="en";
      handleSendMessage(id, {
        from:"driver", fromName:"Conductor",
        text: isEN
          ? `✅ Your trip on ${booking.date} at ${booking.time} has been confirmed. See you soon!`
          : `✅ Tu viaje del ${booking.date} a las ${booking.time} ha sido confirmado. ¡Hasta pronto!`,
        ts: Date.now(),
      });
    }
    setToast("✅ Viaje aceptado y cliente notificado");
  };
  const handleReject=(id,reason)=>{
    fbMutateBookings(p=>p.map(b=>b.id===id?{...b,status:"rejected",rejectionReason:reason||""}:b),setBookings);
    const booking=bookings.find(b=>b.id===id);
    if(booking){
      handleSendMessage(id,{
        from:"driver",fromName:"DRIVER",isSystem:true,ts:Date.now(),
        text:"❌ Reserva rechazada\n📅 "+booking.date+" · "+booking.time+"\n👤 "+booking.guest+"\n📍 "+booking.origin+" → "+booking.destination+(reason?"\n\nMotivo: "+reason:""),
      });
    }
  };
  const handleUpdateFare=(id,fare)=>fbMutateBookings(p=>p.map(b=>b.id===id?{...b,fare}:b),setBookings);
  const handlePayCommission=(id,proof)=>fbMutateBookings(p=>p.map(b=>b.id===id?{...b,commissionStatus:"paid",commissionProof:proof}:b),setBookings);
  const handleStartTrip  =id=>{fbMutateBookings(p=>p.map(b=>b.id===id?{...b,status:"inprogress"}:b),setBookings); setDriverStatus("onroute"); try{localStorage.setItem("nexttrip_trip_started","1");}catch{}};
  const handleEndTrip=id=>{
    fbMutateBookings(p=>p.map(b=>{
      if(b.id!==id) return b;
      const commission = b.fare && !b.isClientBooking ? Math.round(b.fare * COMMISSION_RATE * 100) / 100 : 0;
      return {...b, status:"completed", pendingRating:true,
        commissionAmount: commission,
        commissionStatus: commission > 0 ? "pending" : "none",
      };
    }), setBookings);
    setDriverStatus("free");
    try{localStorage.setItem("nexttrip_trip_started","0");localStorage.setItem("nexttrip_arrived_id","");}catch{}
    sendNotification("Viaje completado", "El viaje ha finalizado. ¡Gracias!", "end-"+id);
  };;
  const handleCancelBooking=(id,reason)=>{
    fbMutateBookings(p=>p.map(b=>b.id===id?{...b,status:"cancelled",cancelReason:reason||"Cancelado por recepción"}:b),setBookings);
    sendNotification("❌ Reserva cancelada",reason||"Cancelado por recepción","cancel-booking-"+id);
    setToast("✕ Reserva cancelada");
  };
  const handleCancelTrip=(id,reason)=>{fbMutateBookings(p=>p.map(b=>b.id===id?{...b,status:"cancelled",cancelReason:reason}:b),setBookings); sendNotification("❌ Viaje cancelado",reason,"trip-cancel-"+id);};
  const handleUploadDoc=(id,doc)=>fbMutateBookings(p=>p.map(b=>b.id===id?{...b,routeDoc:doc}:b),setBookings);
  const handleSaveNote=(id,note)=>fbMutateBookings(p=>p.map(b=>b.id===id?{...b,driverNote:note}:b),setBookings);
  const handleProposePrice=(id,price,note)=>{
    fbMutateBookings(
      p=>p.map(b=>b.id===id?{...b,status:"price_proposed",proposedPrice:price,proposedNote:note||""}:b),
      setBookings,
      (err)=>setToast(err)
    );
    sendNotification("💜 Precio recibido para tu viaje",`El conductor propone ${price} €`,"price-"+id);
    setToast(`💜 Precio de ${price} € enviado al cliente`);
  };
  const handleClientAcceptPrice=(id)=>{
    fbMutateBookings(p=>{
      return p.map(b=>{
        if(b.id!==id)return b;
        const updated={...b,status:"confirmed",fare:b.proposedPrice};
        sendNotification("Precio aceptado",b.guest+" acepto "+b.proposedPrice+" EUR","price-accept-"+id);
        setDriverAlert({type:"price_accepted",booking:updated});
        return updated;
      });
    }, setBookings);
  };
  const handleClientRejectPrice=(id)=>{
    fbMutateBookings(p=>{
      return p.map(b=>{
        if(b.id!==id)return b;
        sendNotification("Precio rechazado",b.guest+" rechazo "+b.proposedPrice+" EUR","price-reject-"+id);
        setDriverAlert({type:"price_rejected",booking:b});
        return {...b,status:"client_rejected"};
      });
    }, setBookings);
  };
  const handleNewBooking=async(data)=>{
    const newBooking={id:Date.now(),...data,status:"pending",createdAt:new Date().toLocaleString("es-ES")};
    try {
      const snap = await fbGet("nexttrip/bookings");
      const existing = snap?.data && Array.isArray(snap.data) ? snap.data : [];
      const merged = [...existing, newBooking];
      await fbSet("nexttrip/bookings", { data: merged, updatedAt: Date.now() });
      try { localStorage.setItem(BOOKINGS_KEY, JSON.stringify(merged)); } catch {}
      setBookings(merged);
    } catch(e) {
      console.error("handleNewBooking error:", e);
      setBookings(p=>{const u=[...p,newBooking];saveBookings(u);return u;});
    }
    setToast("Nueva solicitud de viaje recibida");
    sendNotification("Nueva reserva",data.guest+" - "+data.time+" - "+data.hotel,"new-booking-"+Date.now());
    if(data.isClientBooking){setDriverAlert({type:"new_booking",booking:newBooking});}
  };
  const handleSendMessage=async(bookingId, msg)=>{
    const key = String(bookingId);
    try {
      let updated;
      const docRef = doc(_db, "nexttrip", "messages");
      await runTransaction(_db, async (tx) => {
        const snap = await tx.get(docRef);
        const current = snap.exists() && snap.data()?.data ? snap.data().data : {};
        updated = {...current, [key]: [...(current[key]||[]), msg]};
        tx.set(docRef, { data: updated });
      });
      setMessages(updated);
    } catch(e) {
      console.error("handleSendMessage error:", e);
      // fallback
      setMessages(prev=>{
        const updated={...prev,[key]:[...(prev[key]||[]),msg]};
        fbSet("nexttrip/messages", { data: updated });
        return updated;
      });
    }
    const booking = bookings.find(b=>String(b.id)===key);
    // Only notify if the message is FOR the current screen (not sent BY them)
    const isForDriver = msg.from!=="driver" && isDriverScreen;
    const isForReception = msg.from==="driver" && !isDriverScreen && booking?.employeeId===currentEmployee?.id && !booking?.isClientBooking;
    if(isForDriver || isForReception) {
      const title = msg.from==="driver" ? "💬 Mensaje del conductor" : `💬 ${msg.fromName}`;
      const body = booking ? `${booking.guest} · ${msg.text}` : msg.text;
      sendNotification(title, body, "chat-"+key);
    }
  };
  const handleMarkRead=(bookingId, count)=>{
    setReadCounts(prev=>({...prev,[String(bookingId)]:count}));
  };
  const goHome=()=>{setScreen("roles");setCurrentEmployee(null);};

  const isApp=screen==="driver"||screen==="reception";
  const isDriverScreen=screen==="driver";

  // Calculate unread messages for current user
  const unreadConvos = isApp ? Object.entries(messages).map(([bookingId, msgs])=>{
    const booking = bookings.find(b=>String(b.id)===bookingId);
    if(!booking) return null;

    let relevant;
    if(isDriverScreen) {
      // Driver: only sees messages from clients (VIP app) or reception staff
      // NOT messages from other drivers or system messages they sent themselves
      relevant = msgs.filter(m=>m.from!=="driver");
    } else {
      // Reception: only sees messages from the DRIVER (from:"driver")
      // AND only for bookings that belong to THIS employee
      // AND NOT client VIP bookings (those go to the client app, not reception)
      const isMyBooking = booking.employeeId===currentEmployee?.id;
      const isClientBooking = booking.isClientBooking===true;
      if(!isMyBooking || isClientBooking) return null;
      relevant = msgs.filter(m=>m.from==="driver");
    }

    const readSoFar = readCounts[bookingId]||0;
    const unread = relevant.length - readSoFar;
    if(unread<=0) return null;
    const lastMsg = relevant[relevant.length-1];
    return { bookingId, unread, booking, lastMsg };
  }).filter(Boolean) : [];

  return (
    <ErrorBoundary>
    <div style={{background:"#ffffff",minHeight:"100vh",fontFamily:"'DM Sans',sans-serif",color:"#0f172a",width:"100%",position:"relative"}}>
      <style>{GLOBAL_CSS}</style>

      {/* ── OFFLINE BANNER ── */}
      {!isOnline&&(
        <div style={{
          position:"fixed",top:0,left:0,right:0,zIndex:9999,
          background:"linear-gradient(135deg,#2a1500,#1a0f00)",
          borderBottom:"2px solid #f59e0b",
          padding:"8px 16px",textAlign:"center",
          animation:"slideDown 0.3s ease",
        }}>
          <span style={{color:"#f59e0b",fontSize:12,fontWeight:700}}>
            📡 Sin conexión — los datos se guardan localmente
          </span>
        </div>
      )}
      {!isOnline&&<div style={{height:36}}/>}
      <div style={{position:"fixed",top:-100,right:-100,width:400,height:400,borderRadius:"50%",background:"radial-gradient(circle,rgba(201,169,110,0.04) 0%,transparent 70%)",pointerEvents:"none"}}/>

      {/* ── UNREAD MESSAGES PANEL ── */}
      {unreadConvos.length>0&&(
        <div style={{
          position:"fixed",top:0,left:0,right:0,
          width:"100%",zIndex:500,
          background:"linear-gradient(135deg,#eff6ff,#dbeafe)",
          borderBottom:"3px solid #2563eb",
          boxShadow:"0 4px 24px rgba(37,99,235,0.25)",
          animation:"slideDown 0.3s ease",
        }}>
          <div style={{maxWidth:480,margin:"0 auto"}}>
          {/* Header */}
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"8px 16px 4px"}}>
            <div style={{display:"flex",alignItems:"center",gap:8}}>
              <div style={{background:"#ef4444",borderRadius:"50%",width:8,height:8,animation:"pulse 1s infinite"}}/>
              <span style={{color:"#1e3a8a",fontSize:12,fontWeight:800,letterSpacing:1}}>
                💬 {unreadConvos.reduce((s,c)=>s+c.unread,0)} MENSAJE{unreadConvos.reduce((s,c)=>s+c.unread,0)>1?"S":""} SIN LEER
              </span>
            </div>
          </div>
          {/* Conversation list */}
          {unreadConvos.map(c=>{
            const isVipMsg = c.booking.isClientBooking;
            const msgColor = isVipMsg ? "#a78bfa" : "#2563eb";
            return (
            <div key={c.bookingId} onClick={()=>{
              setChatNotifOpen(c.booking);
              const relevant = (messages[c.bookingId]||[]).filter(m=>isDriverScreen?m.from!=="driver":m.from==="driver");
              handleMarkRead(String(c.bookingId), relevant.length);
            }} style={{
              display:"flex",alignItems:"center",gap:10,
              padding:"8px 16px",borderTop:`1px solid ${isVipMsg?"#e0e7ff":"#dbeafe"}`,
              cursor:"pointer",transition:"background 0.15s",
            }}
              onMouseEnter={e=>e.currentTarget.style.background=isVipMsg?"#e0e7ff":"#dbeafe"}
              onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
              <div style={{width:36,height:36,borderRadius:"50%",flexShrink:0,background:msgColor+"20",border:`1.5px solid ${msgColor}55`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:16}}>
                {isVipMsg?"💜":"💬"}
              </div>
              <div style={{flex:1,minWidth:0}}>
                <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:2}}>
                  <div style={{display:"flex",alignItems:"center",gap:5}}>
                    <span style={{color:"#0f172a",fontSize:12,fontWeight:600}}>{c.booking.guest}</span>
                    {isVipMsg&&<span style={{background:"#a78bfa22",border:"1px solid #a78bfa44",borderRadius:8,padding:"1px 5px",fontSize:8,color:"#a78bfa",fontWeight:700}}>VIP</span>}
                  </div>
                  <span style={{background:"#ef4444",borderRadius:10,padding:"1px 7px",fontSize:10,color:"#fff",fontWeight:700}}>{c.unread}</span>
                </div>
                <div style={{color:"#64748b",fontSize:10,marginBottom:2}}>{c.booking.hotel} · {c.booking.time}</div>
                <div style={{color:"#0f172a",fontSize:11,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",opacity:0.8}}>{c.lastMsg.fromName}: {c.lastMsg.text}</div>
              </div>
            </div>
            );
          })}
          <div style={{height:4}}/>
          </div>
        </div>
      )}

      {/* Padding when unread panel is visible */}
      {unreadConvos.length>0&&isApp&&(
        <div style={{height: 44 + unreadConvos.length * 64}}/>
      )}

      {/* Chat from notification tap */}
      {chatNotifOpen&&(
        <ChatModal
          booking={chatNotifOpen}
          messages={messages}
          onSend={handleSendMessage}
          currentUser={isDriverScreen?null:currentEmployee}
          isDriver={isDriverScreen}
          onClose={()=>setChatNotifOpen(null)}
          onMarkRead={handleMarkRead}
          accentColor={chatNotifOpen.isClientBooking?"#a78bfa":"#2563eb"}
        />
      )}

      <div style={{maxWidth:480,margin:"0 auto",width:"100%"}}>
      {screen==="roles"         &&<RoleSelector onSelect={r=>setScreen(r==="driver"?"driver-login":"reception-auth")} installPrompt={installPrompt}/>}
      {screen==="driver-login"  &&<DriverLogin onLogin={()=>setScreen("driver")} onBack={()=>setScreen("roles")}/>}
      {screen==="reception-auth"&&<ReceptionAuth onLogin={user=>{setCurrentEmployee(user);setScreen("reception");}} onBack={()=>setScreen("roles")}/>}
      </div>

      {isApp&&(
        <div className="app-inner">
        <>
          <div style={{padding:"8px 16px",borderBottom:"2px solid #e2e8f0",background:"#ffffff",position:"sticky",top:0,zIndex:150,boxShadow:"0 2px 8px rgba(37,99,235,0.08)"}}>
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>
              {/* Logo izquierda — grande */}
              <div style={{flexShrink:0,display:"flex",alignItems:"center"}}>
                <RivieraLogo size={72}/>
              </div>
              {/* Derecha: botón DRIVER (driver) o pill empleado (recepción) */}
              {isDriverScreen?(
                <button onClick={()=>setShowDriverMenu(v=>!v)} style={{
                  display:"flex",alignItems:"center",gap:7,
                  background:"#eff6ff",border:"1.5px solid #1e3a8a44",
                  borderRadius:20,padding:"6px 14px 6px 8px",cursor:"pointer",
                  boxShadow:"0 1px 6px rgba(30,58,138,0.12)"
                }}>
                  <div style={{width:28,height:28,borderRadius:"50%",background:"linear-gradient(135deg,#1e3a8a,#2563eb)",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.2" strokeLinecap="round">
                      <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/>
                    </svg>
                  </div>
                  <span style={{color:"#0f172a",fontSize:13,fontWeight:800}}>DRIVER</span>
                  <span style={{color:"#1e3a8a",fontSize:11}}>▾</span>
                  {pendingCount>0&&<div style={{background:"#ef4444",borderRadius:"50%",width:18,height:18,display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,fontWeight:700,color:"#fff",marginLeft:2}}>{pendingCount}</div>}
                </button>
              ):currentEmployee?(
                <button onClick={()=>{setEmpOriginDraft({name:currentEmployee.hotel||"",address:""});setEmpPinView(false);setEmpPinError("");setEmpPinCurrent("");setEmpPinNew("");setEmpPinConfirm("");setShowEmpProfile(true);}} style={{
                  display:"flex",alignItems:"center",gap:6,background:"#eff6ff",
                  border:"1.5px solid #1e3a8a44",borderRadius:20,padding:"4px 12px 4px 4px",cursor:"pointer",
                }}>
                  <div style={{width:26,height:26,borderRadius:"50%",background:currentEmployee.avatar+"25",border:`1.5px solid ${currentEmployee.avatar}55`,display:"flex",alignItems:"center",justifyContent:"center",color:currentEmployee.avatar,fontSize:9,fontWeight:700}}>{initials(currentEmployee.name)}</div>
                  <span style={{color:"#0f172a",fontSize:12,fontWeight:700}}>{currentEmployee.name}</span>
                  <span style={{color:"#64748b",fontSize:10}}>· {currentEmployee.hotel.split(" ").slice(-1)[0]}</span>
                  <span style={{color:"#1e3a8a",fontSize:11}}>▾</span>
                </button>
              ):null}
            </div>
          </div>

          {/* ── EMPLOYEE PROFILE DRAWER ── */}
          {showEmpProfile&&currentEmployee&&(
            <div onClick={()=>setShowEmpProfile(false)} style={{position:"fixed",inset:0,background:"rgba(15,23,42,0.5)",zIndex:1000,display:"flex",alignItems:"flex-end"}}>
              <div onClick={e=>e.stopPropagation()} style={{background:"#ffffff",borderRadius:"22px 22px 0 0",width:"100%",border:"1px solid #e2e8f0",padding:"0 0 36px",position:"relative",zIndex:1001}}>
                <div style={{width:40,height:4,background:"#cbd5e1",borderRadius:4,margin:"14px auto 18px"}}/>
                <div style={{padding:"0 20px"}}>
                  {/* Avatar + nombre */}
                  <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:20,paddingBottom:16,borderBottom:"1px solid #e2e8f0"}}>
                    <div style={{width:52,height:52,borderRadius:"50%",background:currentEmployee.avatar+"25",border:`2px solid ${currentEmployee.avatar}55`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:20,fontWeight:800,color:currentEmployee.avatar,flexShrink:0}}>{initials(currentEmployee.name)}</div>
                    <div>
                      <div style={{color:"#0f172a",fontSize:17,fontWeight:800}}>{currentEmployee.name}</div>
                      <div style={{color:currentEmployee.avatar,fontSize:11,fontWeight:700,marginTop:2}}>{currentEmployee.hotel}</div>
                    </div>
                  </div>

                  {!empPinView?(
                    <>
                      {/* Lugar de trabajo */}
                      <div style={{marginBottom:14}}>
                        <label style={{color:"#1e3a8a",fontSize:10,letterSpacing:2,fontWeight:800,display:"block",marginBottom:5}}>HOTEL / LUGAR DE TRABAJO</label>
                        <input value={empOriginDraft.name} onChange={e=>setEmpOriginDraft({...empOriginDraft,name:e.target.value})}
                          placeholder="Nombre del hotel o lugar de trabajo"
                          style={{width:"100%",background:"#f8fafc",border:`2px solid ${empOriginDraft.name?"#2563eb":"#f59e0b"}`,borderRadius:10,padding:"11px 14px",color:"#0f172a",fontSize:13,fontWeight:700,outline:"none",boxSizing:"border-box"}}/>
                      </div>

                      {/* Punto de partida */}
                      <div style={{marginBottom:6}}>
                        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:5}}>
                          <label style={{color:"#1e3a8a",fontSize:10,letterSpacing:2,fontWeight:800}}>PUNTO DE PARTIDA</label>
                          <button onClick={()=>{
                            const ORIGIN_KEY=`nexttrip_origin_${currentEmployee.id}`;
                            try{const saved=JSON.parse(localStorage.getItem(ORIGIN_KEY)||"{}");setEmpOriginDraft({name:saved.name||"",address:saved.address||""});}catch{}
                            navigator.geolocation&&navigator.geolocation.getCurrentPosition(pos=>{
                              const addr=`${pos.coords.latitude.toFixed(5)},${pos.coords.longitude.toFixed(5)}`;
                              setEmpOriginDraft(d=>({...d,address:addr}));
                            });
                          }} style={{background:"linear-gradient(135deg,#2563eb,#1d4ed8)",border:"none",borderRadius:20,padding:"5px 12px",color:"#ffffff",fontSize:11,fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",gap:5}}>
                            <span style={{fontSize:13}}>📍</span> Usar mi ubicación
                          </button>
                        </div>
                        <input value={empOriginDraft.address} onChange={e=>setEmpOriginDraft({...empOriginDraft,address:e.target.value})}
                          placeholder="Dirección de partida habitual"
                          style={{width:"100%",background:"#f8fafc",border:`2px solid ${empOriginDraft.address?"#2563eb":"#f59e0b"}`,borderRadius:10,padding:"11px 14px",color:"#0f172a",fontSize:13,fontWeight:700,outline:"none",boxSizing:"border-box",marginBottom:8}}/>
                        <button onClick={()=>{
                          const ORIGIN_KEY=`nexttrip_origin_${currentEmployee.id}`;
                          try{localStorage.setItem(ORIGIN_KEY,JSON.stringify(empOriginDraft));}catch{}
                          setShowEmpProfile(false);
                        }} style={{width:"100%",background:"linear-gradient(135deg,#1e3a8a,#2563eb)",border:"none",borderRadius:10,padding:"11px 0",color:"#ffffff",fontSize:13,fontWeight:700,cursor:"pointer",marginBottom:10}}>
                          💾 Guardar datos
                        </button>
                      </div>

                      {/* Cambiar PIN */}
                      <button onClick={()=>setEmpPinView(true)} style={{width:"100%",background:"#f8fafc",border:"1.5px solid #e2e8f0",borderRadius:10,padding:"12px 0",color:"#0f172a",fontSize:13,fontWeight:700,cursor:"pointer",marginBottom:10,display:"flex",alignItems:"center",justifyContent:"center",gap:8}}>
                        🔑 Cambiar PIN de acceso
                      </button>

                      {/* Salir */}
                      <button onClick={()=>{setShowEmpProfile(false);setCurrentEmployee(null);setScreen("roles");}} style={{width:"100%",background:"linear-gradient(135deg,#ef4444,#b91c1c)",border:"none",borderRadius:10,padding:"13px 0",color:"#ffffff",fontSize:13,fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:8}}>
                        🚪 Cerrar sesión
                      </button>
                    </>
                  ):(
                    /* Cambiar PIN view */
                    <div style={{background:"#f8fafc",border:"1.5px solid #2563eb33",borderRadius:12,padding:"16px"}}>
                      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:14}}>
                        <div style={{color:"#1e3a8a",fontSize:13,fontWeight:800}}>🔑 Cambiar PIN</div>
                        <button onClick={()=>setEmpPinView(false)} style={{background:"none",border:"none",color:"#94a3b8",fontSize:18,cursor:"pointer",padding:0}}>✕</button>
                      </div>
                      {["PIN ACTUAL","PIN NUEVO","CONFIRMAR PIN NUEVO"].map((label,idx)=>{
                        const val=[empPinCurrent,empPinNew,empPinConfirm][idx];
                        const setter=[setEmpPinCurrent,setEmpPinNew,setEmpPinConfirm][idx];
                        const borderColor=val.length===4?(idx===2?(empPinNew===empPinConfirm?"#22c55e":"#ef4444"):"#2563eb"):"#e2e8f0";
                        return(
                          <div key={label} style={{marginBottom:12}}>
                            <label style={{color:"#475569",fontSize:10,letterSpacing:1,fontWeight:700,display:"block",marginBottom:4}}>{label}</label>
                            <input type="password" inputMode="numeric" maxLength={4} value={val} onChange={e=>setter(e.target.value.replace(/\D/g,"").slice(0,4))}
                              placeholder="••••"
                              style={{width:"100%",background:"#ffffff",border:`2px solid ${borderColor}`,borderRadius:8,padding:"10px 12px",color:"#0f172a",fontSize:20,fontWeight:700,outline:"none",letterSpacing:6,boxSizing:"border-box",textAlign:"center"}}/>
                          </div>
                        );
                      })}
                      {empPinError&&<div style={{background:"#fff0f0",border:"1px solid #ef444455",borderRadius:8,padding:"8px 10px",color:"#ef4444",fontSize:11,fontWeight:700,marginBottom:10}}>{empPinError}</div>}
                      {empPinSuccess&&<div style={{background:"#f0fdf4",border:"1px solid #22c55e55",borderRadius:8,padding:"8px 10px",color:"#16a34a",fontSize:11,fontWeight:700,marginBottom:10}}>✅ PIN actualizado correctamente</div>}
                      <button onClick={()=>{
                        setEmpPinError("");
                        if(currentEmployee.pin&&empPinCurrent!==currentEmployee.pin){setEmpPinError("PIN actual incorrecto");return;}
                        if(!/^\d{4}$/.test(empPinNew)){setEmpPinError("El PIN debe tener 4 dígitos");return;}
                        if(empPinNew!==empPinConfirm){setEmpPinError("Los PINs no coinciden");return;}
                        const users=loadUsers();
                        const updated=users.map(u=>u.id===currentEmployee.id?{...u,pin:empPinNew}:u);
                        try{localStorage.setItem(USERS_KEY,JSON.stringify(updated));}catch{}
                        setEmpPinSuccess(true);
                        setEmpPinCurrent("");setEmpPinNew("");setEmpPinConfirm("");
                        setTimeout(()=>{setEmpPinSuccess(false);setEmpPinView(false);},1800);
                      }} style={{width:"100%",background:"linear-gradient(135deg,#1e3a8a,#2563eb)",border:"none",borderRadius:8,padding:"11px 0",color:"#ffffff",fontSize:13,fontWeight:700,cursor:"pointer"}}>
                        Guardar nuevo PIN
                      </button>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}



          <div style={{padding:"20px 20px 0"}}>
            {isDriverScreen&&!notifDismissed&&<NotifPermissionPrompt onDismiss={()=>setNotifDismissed(true)}/>}
            {isDriverScreen
              ?<DriverView bookings={bookings} onAccept={handleAccept} onReject={handleReject} onUpdateFare={handleUpdateFare} onPayCommission={handlePayCommission} onStartTrip={handleStartTrip} onEndTrip={handleEndTrip} onCancelTrip={handleCancelTrip} onUploadDoc={handleUploadDoc} onProposePrice={handleProposePrice} onSaveNote={handleSaveNote} setToast={setToast} messages={messages} onSendMessage={handleSendMessage} onMarkRead={handleMarkRead} driverStatus={driverStatus} setDriverStatus={setDriverStatus} blockedSlots={blockedSlots} onToggleBlock={handleToggleBlock} serviceStatus={serviceStatus} onSetService={handleSetService} showDriverMenu={showDriverMenu} setShowDriverMenu={setShowDriverMenu} goHome={goHome} openPriceConfig={()=>{setDraftPriceClient(String(driverPriceClient));setDraftPriceRecep(String(driverPriceRecep));setDriverPriceConfig(true);}}/>
              :<ReceptionistView employee={currentEmployee} bookings={bookings} onNewBooking={handleNewBooking} onCancelBooking={handleCancelBooking} messages={messages} onSendMessage={handleSendMessage} onMarkRead={handleMarkRead} driverStatus={driverStatus} blockedSlots={blockedSlots} serviceStatus={serviceStatus}/>
            }
          </div>
        </>
        </div>
      )}
      {inAppAlert&&<ReminderBanner alert={inAppAlert} onDismiss={dismissAlert}/>}
      {driverAlert&&isApp&&<DriverAlertBanner alert={driverAlert} onDismiss={()=>setDriverAlert(null)}/>}
      {showInstall&&<div style={{position:"fixed",bottom:20,left:"50%",transform:"translateX(-50%)",zIndex:9998,
        background:"#ffffff",border:"2px solid #2563eb",borderRadius:20,
        padding:"16px 20px",display:"flex",alignItems:"center",gap:14,
        boxShadow:"0 8px 32px rgba(37,99,235,0.25)",width:"calc(100% - 40px)",maxWidth:380}}>
        {/* Icon */}
        <div style={{width:52,height:52,borderRadius:14,overflow:"hidden",flexShrink:0,boxShadow:"0 2px 8px rgba(0,0,0,0.2)"}}>
          <img src="/icon-driver.svg" width="52" height="52" alt="VELO Transfers" style={{objectFit:"cover"}}/>
        </div>
        {/* Text */}
        <div style={{flex:1}}>
          <div style={{color:"#1e3a8a",fontSize:14,fontWeight:800,marginBottom:2}}>{"Instalar VELO Transfers"}</div>
          <div style={{color:"#2563eb",fontSize:11,fontWeight:600}}>{"VELO Private Transfers"}</div>
          <div style={{color:"#94a3b8",fontSize:10,marginTop:1}}>{"Añadir a pantalla de inicio"}</div>
        </div>
        {/* Install button */}
        <button onClick={handleInstall} style={{
          background:"linear-gradient(135deg,#1e3a8a,#2563eb)",border:"none",borderRadius:12,
          color:"#ffffff",fontSize:12,fontWeight:700,padding:"10px 16px",cursor:"pointer",
          boxShadow:"0 2px 8px rgba(37,99,235,0.35)",flexShrink:0,
        }}>{"Instalar"}</button>
        <button onClick={()=>setShowInstall(false)} style={{background:"#f1f5f9",border:"none",color:"#64748b",fontSize:16,cursor:"pointer",padding:"6px 8px",borderRadius:8,flexShrink:0}}>{"X"}</button>
      </div>}
      {/* ── PRICE CONFIG MODAL ── */}
      {driverPriceConfig&&(
        <div style={{position:"fixed",inset:0,background:"rgba(15,23,42,0.5)",zIndex:200,display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
          <div style={{background:"#f8fafc",border:"1.5px solid #22c55e44",borderRadius:20,padding:24,width:"100%",maxWidth:380}}>
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:20}}>
              <div>
                <div style={{color:"#0f172a",fontSize:16,fontFamily:"'Inter',sans-serif",fontWeight:700}}>⚙️ Precio por km</div>
                <div style={{color:"#64748b",fontSize:11,marginTop:2}}>Se aplica en todos los cálculos automáticos</div>
              </div>
              <button onClick={()=>setDriverPriceConfig(false)} style={{background:"#f1f5f9",border:"1px solid #2a3a4a",borderRadius:8,padding:"4px 10px",color:"#64748b",fontSize:12,cursor:"pointer"}}>✕</button>
            </div>
            <div style={{marginBottom:16}}>
              <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
                <span style={{background:"#2563eb18",border:"1px solid #2563eb55",borderRadius:6,padding:"2px 8px",color:"#2563eb",fontSize:10,fontWeight:700}}>📱 VELO APP</span>
              </div>
              <div style={{display:"flex",alignItems:"center",gap:8}}>
                <input type="number" step="0.05" min="1" max="20" value={draftPriceClient}
                  onChange={e=>setDraftPriceClient(e.target.value)}
                  style={{flex:1,background:"#ffffff",border:"1.5px solid #2563eb55",borderRadius:10,color:"#0f172a",fontSize:20,fontWeight:700,padding:"10px 14px",outline:"none",textAlign:"center"}}/>
                <span style={{color:"#64748b",fontSize:14}}>€/km</span>
              </div>
              {draftPriceClient&&<div style={{color:"#2563eb",fontSize:10,marginTop:4}}>Ej. 30km → {Math.max(30,Math.round(30*Number(draftPriceClient)*100)/100)} €</div>}
            </div>
            <div style={{marginBottom:24}}>
              <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
                <span style={{background:"#1e3a8a18",border:"1px solid #1e3a8a44",borderRadius:6,padding:"2px 8px",color:"#1e3a8a",fontSize:10,fontWeight:700}}>🏢 V. TRANSFER</span>
              </div>
              <div style={{display:"flex",alignItems:"center",gap:8}}>
                <input type="number" step="0.05" min="1" max="20" value={draftPriceRecep}
                  onChange={e=>setDraftPriceRecep(e.target.value)}
                  style={{flex:1,background:"#ffffff",border:"1.5px solid #2563eb44",borderRadius:10,color:"#0f172a",fontSize:20,fontWeight:700,padding:"10px 14px",outline:"none",textAlign:"center"}}/>
                <span style={{color:"#64748b",fontSize:14}}>€/km</span>
              </div>
              {draftPriceRecep&&<div style={{color:"#2563eb",fontSize:10,marginTop:4}}>Ej. 30km → {Math.max(30,Math.round(30*Number(draftPriceRecep)*100)/100)} €</div>}
            </div>
            <div style={{display:"flex",gap:8}}>
              <button onClick={()=>setDriverPriceConfig(false)} style={{flex:1,background:"#f1f5f9",border:"1px solid #2a3a4a",borderRadius:10,padding:"11px 0",color:"#64748b",fontSize:12,fontWeight:600,cursor:"pointer"}}>Cancelar</button>
              <button onClick={()=>{
                const c=Math.max(1,Number(draftPriceClient)||3.15);
                const r=Math.max(1,Number(draftPriceRecep)||3.15);
                setDriverPriceClient(c);setDriverPriceRecep(r);
                try{localStorage.setItem("ntprice_client",String(c));localStorage.setItem("ntprice_recep",String(r));}catch{}
                fbGet("nexttrip/status").then(cur=>{fbSet("nexttrip/status",{...(cur||{}),pricePerKmClient:c,pricePerKmRecep:r,updatedAt:Date.now()});});
                setDriverPriceConfig(false);
                setToast("✅ Precios: VELO App "+c+"€/km · V.Transfer "+r+"€/km");
              }} style={{flex:2,background:"linear-gradient(135deg,#22c55e,#16a34a)",border:"none",borderRadius:10,padding:"11px 0",color:"#fff",fontSize:13,fontWeight:700,cursor:"pointer"}}>
                ✓ Guardar
              </button>
            </div>
          </div>
        </div>
      )}
      {toast&&<Toast msg={toast} onClose={()=>setToast(null)}/>}
    </div>
    </ErrorBoundary>
  );
}